import { sleep, check } from 'k6';
export let options = {
  scenarios: {
    throughput: {
      executor: 'constant-arrival-rate',
      rate: 150000, // events per second
      timeUnit: '1s',
      preAllocatedVUs: 2000,
      maxVUs: 5000,
    }
  }
};
export default function () {
